import re
from dataclasses import dataclass
from pathlib import Path
from urllib.parse import urlparse

import httpx

LINK = re.compile(r"\[[^\]]*\]\((https?://[^)\s]+)\)")


@dataclass
class Problem:
    line: int
    url: str
    reason: str


def find_markdown(path: str) -> list[Path]:
    p = Path(path)
    if p.is_file():
        return [p] if p.suffix == ".md" else []
    return sorted(p.rglob("*.md"))


def check_file(path: Path, ignore: list[str], timeout: float) -> list[Problem]:
    problems = []
    with httpx.Client(timeout=timeout, follow_redirects=True) as client:
        for n, text in enumerate(path.read_text(encoding="utf-8").splitlines(), 1):
            for url in LINK.findall(text):
                if urlparse(url).hostname in ignore:
                    continue
                try:
                    status = client.head(url).status_code
                    if status >= 400:
                        problems.append(Problem(n, url, f"HTTP {status}"))
                except httpx.HTTPError as e:
                    problems.append(Problem(n, url, type(e).__name__))
    return problems
